interface ICommand<TSelf> where TSelf : ICommand<TSelf>
{
    static abstract string Name { get; }
    static abstract TSelf Parse(string args);
    void Run();
}

record Move(int Steps) : ICommand<Move>
{
    public static string Name => "move";
    public static Move Parse(string args) => new(int.Parse(args));
    public void Run() => Console.WriteLine($"идём на {Steps}");
}

static void Exec<T>(string args) where T : ICommand<T> =>
    T.Parse(args).Run();   // статический вызов через параметр типа
